    throw new Error(`LEAD_SOURCE_INVALID item=${index}`);
  }

  if (
    idempotencyKey.length < 16 ||
    idempotencyKey.length > 191 ||
    !/^[A-Za-z0-9][A-Za-z0-9._:-]*$/.test(idempotencyKey)
  ) {
    throw new Error(`LEAD_IDEMPOTENCY_KEY_INVALID item=${index}`);
  }

  return {
    json: finalItem,
    pairedItem: {
      item: index,
    },
  };
});

